def edit(t):
    for a,b in REPLACE.items():t=t.replace(a,b)
    t=t.replace('Например, можно заменить, например,','Например, можно заменить')
    # Historical marker comments carry provenance, retained in the source ledger.
    t=re.sub(r'<!-- (?!/?EDIT:)[^>]+-->','',t)
    return t
def main():
    cov=load();course=json.loads((ROOT/'course.json').read_text(encoding='utf8'))
    for c in course['chapters']:
        text=(ROOT/c['path']).read_text(encoding='utf8')
        if edit(text)!=text:transform(c['path'],edit,'История обсуждения убрана из учебного текста; исходный вопрос сформулирован непосредственно, происхождение осталось в реестре.',cov);save(cov)
if __name__=='__main__':main()
